vistas.css:
body{padding:0!important;background:rgba(62,63,63,.5)!important}
.stage{position:relative;padding-top:70px;display:flex;align-items:flex-end;justify-content:center}
.sheet{width:100%;max-width:480px;background:#FFFFFF;border-radius:28px 28px 0 0;box-shadow:0 -20px 60px rgba(62,63,63,.18);overflow:hidden}
.hero{position:relative;height:128px;background:#F5F3F0;overflow:hidden}
.hero:before{content:'';position:absolute;width:300px;height:300px;border-radius:50%;right:-70px;top:-150px;background:#FAFAFA}
.hero:after{content:'';position:absolute;width:190px;height:190px;border-radius:50%;left:-60px;bottom:-120px;background:#EDE9E4}
.stone{position:absolute;left:50%;top:50%;width:66px;height:66px;margin:-33px 0 0 -33px;border-radius:50%;z-index:1;background:radial-gradient(circle at 40% 34%,#F7F5F2 0%,#EFECE8 42%,#E3DFDA 78%,#D3CEC8 100%);box-shadow:0 0 0 2px rgba(233,130,106,.35),0 0 26px 6px rgba(233,130,106,.45),0 10px 18px -6px rgba(90,70,60,.35)}
.x{position:absolute;top:12px;right:12px;z-index:2;width:40px;height:40px;border-radius:50%;background:rgba(255,255,255,.85);color:#938B8A;display:flex;align-items:center;justify-content:center;font-size:17px}
.body{padding:18px 22px 22px}
.kick{font-size:10px;font-weight:600;letter-spacing:.22em;text-transform:uppercase;color:#938B8A;display:flex;align-items:center;gap:8px}
.kick i{width:7px;height:7px;border-radius:50%;background:#E9826A}
.h1{font-family:'Valky','Cormorant Garamond',Georgia,serif;font-size:26px;line-height:1.15;margin:6px 0 2px;color:#3E3F3F}
.sub{font-size:12.5px;line-height:1.6;color:#938B8A;margin:0}
h3{font-size:9.5px;font-weight:700;letter-spacing:.16em;text-transform:uppercase;color:#938B8A;margin:18px 0 9px}
.item{display:flex;gap:13px;align-items:center;background:#F5F3F0;border:1px solid #EDEAE6;border-radius:16px;padding:10px 12px 10px 10px;margin-bottom:8px}
.th{position:relative;flex-shrink:0;width:58px;height:78px;border-radius:12px;background:linear-gradient(160deg,#E8DCCD,#D8C6B4)}
.th:after{content:'';position:absolute;left:50%;top:50%;width:26px;height:26px;margin:-13px 0 0 -13px;border-radius:50%;background:rgba(233,130,106,.92)}
.th:before{content:'';position:absolute;z-index:1;left:50%;top:50%;margin:-6px 0 0 -3px;border-left:9px solid #fff;border-top:6px solid transparent;border-bottom:6px solid transparent}
.t{display:block;font-size:14px;font-weight:600;color:#3E3F3F;line-height:1.3}
.r{display:block;font-size:11.5px;color:#938B8A;line-height:1.45;margin-top:3px}
.m{display:inline-block;margin-top:6px;font-size:9px;font-weight:700;letter-spacing:.12em;text-transform:uppercase;color:#B4553C;background:#FCEDE8;border:1px solid #E9826A;border-radius:999px;padding:2px 8px}
.fab{position:absolute;right:0;top:10px;width:40px;height:48px;border:1.5px solid #E9826A;border-right:0;border-radius:24px 0 0 24px;background:#FFFFFF;color:#3E3F3F;display:flex;align-items:center;justify-content:center;padding-left:3px;font:400 23px/1 'Valky','Cormorant Garamond',Georgia,serif;box-shadow:-6px 10px 26px -12px rgba(90,70,60,.35)}
